import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.*;
import java.util.regex.*;
import javax.swing.text.*;
import javax.swing.text.html.*;
import javax.swing.text.html.parser.ParserDelegator;

final class WorkbenchCore {
    record Finding(String severity,String title,String url,String evidence,String confidence) {}
    record AttackResult(int number,String payload,VulnApp.Packet request,URI url,VulnApp.Reply reply,long millis,String error) {}
    static final String MARK="§";
    static List<String> payloadRequests(String template,List<List<String>> sets,String type,int limit){
        if(template.length()>1024*1024||sets.isEmpty())throw new IllegalArgumentException("Template excede 1 MiB ou faltam payloads");
        String[] pieces=template.split(MARK,-1);if(pieces.length<3||pieces.length%2==0)throw new IllegalArgumentException("Marque posições como §valor§");int positions=(pieces.length-1)/2;List<String> output=new ArrayList<>();List<String> first=sets.get(0);if(first.isEmpty())throw new IllegalArgumentException("Lista de payloads vazia");
        switch(type){
            case "Sniper"->{for(int p=0;p<positions;p++)for(String value:first){String[] values=new String[positions];for(int k=0;k<positions;k++)values[k]=pieces[k*2+1];values[p]=value;append(output,render(pieces,values),limit);}}
            case "Battering ram"->{for(String value:first){String[] values=new String[positions];Arrays.fill(values,value);append(output,render(pieces,values),limit);}}
            case "Pitchfork"->{if(sets.size()<positions)throw new IllegalArgumentException("Uma lista por posição é necessária (separe por linha ---)");int n=sets.stream().limit(positions).mapToInt(List::size).min().orElse(0);for(int i=0;i<n;i++){String[] values=new String[positions];for(int k=0;k<positions;k++)values[k]=sets.get(k).get(i);append(output,render(pieces,values),limit);}}
            case "Cluster bomb"->{if(sets.size()<positions)throw new IllegalArgumentException("Uma lista por posição é necessária (separe por linha ---)");expand(pieces,sets,new String[positions],0,output,limit);}
            default->throw new IllegalArgumentException("Tipo de ataque desconhecido");
        }return output;
    }
    static void append(List<String> list,String value,int limit){if(list.size()>=limit||(long)value.length()*(list.size()+1)>32*1024*1024)throw new IllegalArgumentException("Ataque excede o limite de requests ou 32 MiB de templates");list.add(value);}
    static void expand(String[] pieces,List<List<String>> sets,String[] values,int position,List<String> result,int limit){if(position==values.length){append(result,render(pieces,values),limit);return;}for(String value:sets.get(position)){values[position]=value;expand(pieces,sets,values,position+1,result,limit);}}
    static String render(String[] pieces,String[] values){StringBuilder b=new StringBuilder(pieces[0]);for(int i=0;i<values.length;i++)b.append(values[i]).append(pieces[i*2+2]);return b.toString();}
    static List<List<String>> sets(String text,boolean encode){List<List<String>> sets=new ArrayList<>();for(String group:text.split("(?m)^---\\s*$")){List<String> values=new ArrayList<>();for(String value:group.split("\\R",-1)){if(value.isEmpty())continue;values.add(encode?URLEncoder.encode(value,StandardCharsets.UTF_8):value);}sets.add(values);}return sets;}
    static void attack(String template,String base,List<List<String>> sets,String type,int delay,int limit,AtomicBoolean stop,Consumer<AttackResult> sink) throws Exception {
        List<String> messages=payloadRequests(template,sets,type,limit);int i=0;for(String raw:messages){if(stop.get()||Thread.currentThread().isInterrupted())break;VulnApp.Packet packet=null;URI uri=null;long start=System.nanoTime();try{packet=VulnApp.parse(raw.getBytes(VulnApp.WIRE));uri=packet.uri(base);VulnApp.Reply reply=VulnApp.perform(packet,uri);sink.accept(new AttackResult(++i,raw,packet,uri,reply,(System.nanoTime()-start)/1000000,""));}catch(Exception ex){sink.accept(new AttackResult(++i,raw,packet,uri,null,(System.nanoTime()-start)/1000000,ex.getMessage()));}if(delay>0)Thread.sleep(delay);}
    }
    static String raw(VulnApp.Reply reply){return new String(reply.raw(),VulnApp.WIRE);}
    static String body(VulnApp.Reply reply){String raw=raw(reply);int at=raw.indexOf("\r\n\r\n");return at<0?"":raw.substring(at+4);}
    static Map<String,List<String>> headers(VulnApp.Reply reply){Map<String,List<String>> result=new LinkedHashMap<>();String raw=raw(reply);int at=raw.indexOf("\r\n\r\n");if(at<0)return result;String[] lines=raw.substring(0,at).split("\r\n");for(int i=1;i<lines.length;i++){int colon=lines[i].indexOf(':');if(colon>0)result.computeIfAbsent(lines[i].substring(0,colon).toLowerCase(Locale.ROOT),k->new ArrayList<>()).add(lines[i].substring(colon+1).trim());}return result;}
    static List<Finding> passive(URI uri,VulnApp.Reply reply){List<Finding> out=new ArrayList<>();Map<String,List<String>> h=headers(reply);String type=String.join(" ",h.getOrDefault("content-type",List.of())).toLowerCase(Locale.ROOT);boolean html=type.contains("text/html");String url=uri.toString();
        if(html&&!h.containsKey("content-security-policy"))out.add(new Finding("Low","Content-Security-Policy ausente",url,"Resposta HTML sem header CSP; ausência não prova exploração.","Observed"));
        if(html&&!h.containsKey("x-frame-options")&&!String.join(" ",h.getOrDefault("content-security-policy",List.of())).toLowerCase(Locale.ROOT).contains("frame-ancestors"))out.add(new Finding("Low","Proteção de framing ausente",url,"Sem X-Frame-Options ou CSP frame-ancestors.","Observed"));
        if(html&&!String.join(" ",h.getOrDefault("x-content-type-options",List.of())).equalsIgnoreCase("nosniff"))out.add(new Finding("Low","X-Content-Type-Options ausente",url,"Resposta HTML sem nosniff.","Observed"));
        if(uri.getScheme().equals("https")&&!h.containsKey("strict-transport-security"))out.add(new Finding("Low","HSTS ausente",url,"Resposta HTTPS sem Strict-Transport-Security.","Observed"));
        for(String cookie:h.getOrDefault("set-cookie",List.of())){String lc=cookie.toLowerCase(Locale.ROOT);String name=cookie.split("=",2)[0];if(!lc.matches("(?s).*;\\s*httponly(?:;|$).*"))out.add(new Finding("Low","Cookie sem HttpOnly",url,"Cookie "+name+" não declara HttpOnly; avaliar finalidade.","Observed"));if(uri.getScheme().equals("https")&&!lc.matches("(?s).*;\\s*secure(?:;|$).*"))out.add(new Finding("Medium","Cookie sem Secure",url,"Cookie "+name+" em HTTPS sem Secure.","Observed"));if(!lc.contains("samesite="))out.add(new Finding("Info","Cookie sem SameSite explícito",url,"Cookie "+name+" usa comportamento padrão do cliente.","Observed"));}
        Matcher error=Pattern.compile("(?i)(SQL syntax.*?MySQL|org\\.postgresql\\.util\\.PSQLException|java\\.lang\\.[A-Za-z]+Exception|Traceback \\(most recent call last\\))").matcher(body(reply));if(error.find())out.add(new Finding("Medium","Detalhe de erro exposto",url,error.group(),"Observed"));return out;
    }
    static boolean sameOrigin(URI a,URI b){return Objects.equals(a.getScheme(),b.getScheme())&&a.getHost()!=null&&a.getHost().equalsIgnoreCase(b.getHost())&&effectivePort(a)==effectivePort(b);}
    static int effectivePort(URI u){return u.getPort()<0?(u.getScheme().equals("https")?443:80):u.getPort();}
    static List<URI> links(URI base,String html) throws IOException {Set<URI> out=new LinkedHashSet<>();new ParserDelegator().parse(new StringReader(html),new HTMLEditorKit.ParserCallback(){public void handleStartTag(HTML.Tag tag,MutableAttributeSet attrs,int pos){collect(tag,attrs);}public void handleSimpleTag(HTML.Tag tag,MutableAttributeSet attrs,int pos){collect(tag,attrs);}void collect(HTML.Tag tag,MutableAttributeSet attrs){Object value=attrs.getAttribute(tag==HTML.Tag.FORM?HTML.Attribute.ACTION:HTML.Attribute.HREF);if(value==null)return;try{URI u=base.resolve(value.toString());u=new URI(u.getScheme(),u.getAuthority(),u.getPath(),u.getQuery(),null);if(sameOrigin(base,u)&&u.getUserInfo()==null)out.add(u);}catch(Exception ignored){}}},true);return new ArrayList<>(out);}
    interface Progress {void accept(VulnApp.Packet p,URI u,VulnApp.Reply reply);}
    static void scan(URI seed,int maxPages,boolean active,int delay,AtomicBoolean stop,Consumer<Finding> sink,Progress progress) throws Exception {
        VulnApp.Packet.checked(seed);ArrayDeque<URI> queue=new ArrayDeque<>();Set<URI> visited=new LinkedHashSet<>();queue.add(seed);
        while(!queue.isEmpty()&&visited.size()<maxPages&&!stop.get()){
            URI uri=queue.poll();if(!sameOrigin(seed,uri)||!visited.add(uri))continue;VulnApp.Packet packet=get(uri);VulnApp.Reply reply;
            try{reply=VulnApp.perform(packet,uri);}catch(Exception ex){sink.accept(new Finding("Info","Falha de coleta",uri.toString(),String.valueOf(ex.getMessage()),"Observed"));continue;}progress.accept(packet,uri,reply);passive(uri,reply).forEach(sink);
            String text=body(reply);if(headers(reply).getOrDefault("content-type",List.of()).stream().anyMatch(v->v.contains("text/html")))for(URI link:links(uri,text))if(!visited.contains(link)&&queue.size()<200)queue.add(link);
            if(active&&uri.getRawQuery()!=null){String[] params=uri.getRawQuery().split("&");for(int i=0;i<Math.min(params.length,10)&&!stop.get();i++){String key=params[i].split("=",2)[0];String marker="rea_"+UUID.randomUUID().toString().replace("-","").substring(0,12);String[] changed=params.clone();changed[i]=key+"="+marker;URI probe=URI.create(uri.getScheme()+"://"+uri.getRawAuthority()+uri.getRawPath()+"?"+String.join("&",changed));VulnApp.Packet probePacket=get(probe);try{VulnApp.Reply tested=VulnApp.perform(probePacket,probe);progress.accept(probePacket,probe,tested);if(body(tested).contains(marker))sink.accept(new Finding("Info","Entrada refletida na resposta",probe.toString(),"Parâmetro "+key+" refletiu marcador único "+marker+". Isto NÃO confirma XSS.","Observed"));}catch(Exception ex){sink.accept(new Finding("Info","Falha no probe",probe.toString(),String.valueOf(ex.getMessage()),"Observed"));}if(delay>0)Thread.sleep(delay);}}
            if(delay>0)Thread.sleep(delay);
        }
    }
    static VulnApp.Packet get(URI uri){LinkedHashMap<String,String> headers=new LinkedHashMap<>();headers.put("Host",uri.getRawAuthority());headers.put("User-Agent","VULN/2.0");headers.put("Accept","text/html,application/json");return new VulnApp.Packet("GET",(uri.getRawPath().isEmpty()?"/":uri.getRawPath())+(uri.getRawQuery()==null?"":"?"+uri.getRawQuery()),"HTTP/1.1",headers,new byte[0]);}
    static String tokenAnalysis(List<String> tokens){if(tokens.size()<2)throw new IllegalArgumentException("Forneça pelo menos dois tokens, um por linha");Map<String,Integer> chars=new HashMap<>();Set<String> distinct=new HashSet<>(tokens);int length=0;for(String token:tokens)for(int point:token.codePoints().toArray()){chars.merge(new String(Character.toChars(point)),1,Integer::sum);length++;}double entropy=0;for(int count:chars.values()){double p=(double)count/length;entropy-=p*Math.log(p)/Math.log(2);}double average=tokens.stream().mapToInt(String::length).average().orElse(0);StringBuilder out=new StringBuilder(String.format(Locale.ROOT,"Samples: %d%nDistinct: %d%nDuplicates: %d%nMean length: %.2f characters%nAlphabet size: %d%nEmpirical character entropy: %.4f bits/character%n%n",tokens.size(),distinct.size(),tokens.size()-distinct.size(),average,chars.size(),entropy));int min=tokens.stream().mapToInt(String::length).min().orElse(0);for(int i=0;i<Math.min(min,256);i++){Map<Character,Integer> frequency=new HashMap<>();for(String t:tokens)frequency.merge(t.charAt(i),1,Integer::sum);out.append("Position ").append(i).append(": ").append(frequency.size()).append(" distinct symbols\n");}return out.append("\nEstatística descritiva da amostra; não é estimativa da entropia criptográfica do gerador nem certificado de aleatoriedade.\n").toString();}
    static String compare(String a,String b){String[] left=a.split("\\R",-1),right=b.split("\\R",-1);if(left.length>5000||right.length>5000)throw new IllegalArgumentException("Limite de 5000 linhas por entrada");StringBuilder out=new StringBuilder();int changes=0;for(int i=0;i<Math.max(left.length,right.length);i++){String x=i<left.length?left[i]:null,y=i<right.length?right[i]:null;if(!Objects.equals(x,y)){changes++;out.append("@@ line ").append(i+1).append(" @@\n");if(x!=null)out.append("- ").append(x).append('\n');if(y!=null)out.append("+ ").append(y).append('\n');}}return "Changed line positions: "+changes+"\n"+out;}
}
